//! canonical-laws.rs — twin of skills/engine/canonical-laws.mjs: DATA statics pressed by the crossing + the
//! hand-ported accessor. NAMES ARE CONTRACT: statics and fns carry exact JS names.
// QUALITY: 80/100 — pressed statics + trivial hand accessor; blob unreadable by design, surface fully tested
use serde_json::Value;
use std::sync::LazyLock;

pub static CANONICAL_LAWS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"slug":"NEVER_FALSIFY_PROTOCOL_STATE","kind":"constitutional","domain":"audit","title":"Never falsify protocol state","statement":"Never manually write rows to sacred_timeline (the audit table), set qa_pass markers, fake digital_prints, or otherwise simulate audit events. All audit rows must originate from with-audit running over a real skill execution.","rationale":"Falsified audit data permanently poisons the Merkle chain (verify-chain cannot distinguish a real event from a forged one with valid sha). Once trust in the chain is gone, the entire substrate loses its safety net. Established 2026-05-10 by human:dani after a real incident.","enforcement":"hard","enforcement_hook":"law-hook-no-direct-audit-write","established_by":"human:dani","source_card":null,"clauses":[{"clause_type":"antipattern","text":"directly inserting forged rows into sacred_timeline via raw db.prepare"},{"clause_type":"antipattern","text":"updating qa_events to mark status pass without QA actually running"},{"clause_type":"antipattern","text":"using --unsafe-skill to bypass with-audit when the goal IS to mutate audited state"},{"clause_type":"example","text":"Legitimate path: call the appropriate action (e.g., board-keeper.card.update) which routes through with-audit transparently"},{"clause_type":"consequence","text":"Caught: card revoked + violation logged. Pattern repeats: agent permission revoked."}]},{"slug":"HISTORY_IS_SACRED_NO_REVERT","kind":"constitutional","domain":"audit","title":"History is sacred — no revert without explicit human request","statement":"Never run git revert, git reset, force-push, or any operation that erases or rewrites published commits unless the human explicitly requests it (\"reverta X\", \"desfaz Y\").","rationale":"History preserves the trail of thinking including mistakes. Reverting destroys learning signal AND forces future-AI to reconstruct context from scratch. When something goes wrong, fix forward via a NEW commit.","enforcement":"hard","enforcement_hook":"law-hook-no-destructive-git","established_by":"human:dani","source_card":null,"clauses":[{"clause_type":"antipattern","text":"git revert HEAD~3..HEAD (without explicit \"revert\" instruction)"},{"clause_type":"antipattern","text":"git reset --hard origin/main (without explicit \"reset\" instruction)"},{"clause_type":"exception","text":"Human types literally: \"reverta X\", \"desfaz Y\", \"rebaseia Z\" — that is the explicit opt-in"},{"clause_type":"example","text":"Bug shipped → write a new commit that fixes the bug. Keep the bug commit in history."}]},{"slug":"NEVER_BYPASS_WITH_AUDIT","kind":"constitutional","domain":"audit","title":"All mutations to auditable entities go through with-audit","statement":"Direct UPDATE/INSERT/DELETE statements against audited tables (cards, agents, actions, memory.memories, laws.laws) are forbidden when made from action code. Mutations must compose through with-audit which captures before/after diff into sacred_timeline.","rationale":"Direct DB writes leave no audit trail. Future-anyone (AI or human) cannot answer \"when did this change?\" or \"why is this in this state?\" without a chain entry. The GAP-CARD-UPDATE-ACTION incident proved this — a body update via direct UPDATE was invisible to the audit chain.","enforcement":"hard","enforcement_hook":"law-hook-mutation-via-with-audit","established_by":"human:dani+claude","source_card":"GAP-CARD-UPDATE-ACTION","clauses":[{"clause_type":"antipattern","text":"directly mutating the cards table via raw prepared statements from inside a skill"},{"clause_type":"example","text":"Call card-update skill (which composes with with-audit) instead of directly mutating cards table"},{"clause_type":"exception","text":"Seed-time bootstrap (seedCanonical) — bootstrap creates baseline state, audit chain starts AFTER bootstrap"},{"clause_type":"consequence","text":"Audit-gap canary test will detect direct UPDATEs that bypass the chain"}]},{"slug":"NEVER_COMMIT_SECRETS","kind":"constitutional","domain":"security","title":"Never commit credentials, tokens, or keys to git","statement":"No .env files, credential JSONs, private keys, API tokens, HMAC secrets, or session cookies in any commit. The .antiloki/auth/ directory MUST stay in .gitignore.","rationale":"Secrets in git history are permanent even after deletion (every clone retains the leak). Public repos compound this to a global breach.","enforcement":"hard","enforcement_hook":"law-hook-no-secrets-in-commit","established_by":"system:bootstrap","clauses":[{"clause_type":"antipattern","text":"git add .antiloki/auth/dev.key"},{"clause_type":"antipattern","text":"Hardcoded API key in source file"},{"clause_type":"example","text":"Use env vars referenced from .gitignored .env files (process.env.API_KEY)"},{"clause_type":"consequence","text":"Rotate compromised secret + audit access logs + git-filter-repo the leaked SHA"}]},{"slug":"GOD_MODE_TTY_REQUIRED","kind":"constitutional","domain":"security","title":"GOD agent invocations require interactive TTY or explicit authorization","statement":"The god agent identity (--as god) is callable only when process.stdin.isTTY === true OR ANTILOKI_GOD_AUTHORIZED=true is set in the environment. AI subprocesses without PTY are blocked from invoking god-keyed actions even if they read the key file.","rationale":"GOD has unrestricted permissions including writes to bin/ and schema migrations. Restricting to interactive terminals limits the blast radius if an AI agent ever gains code execution beyond its intended scope. The env-var escape exists for legitimate tooling (cron, user scripts) but raises an explicit signal.","enforcement":"hard","enforcement_hook":"auth-verify","established_by":"human:dani+claude","source_card":null,"clauses":[{"clause_type":"example","text":"User types \"antiloki --as god system.law.add ...\" in their terminal: TTY exists → allowed"},{"clause_type":"antipattern","text":"MCP server (no TTY) attempts to invoke a god action via auth_token: blocked by auth-verify"},{"clause_type":"exception","text":"ANTILOKI_GOD_AUTHORIZED=true allows headless god invocation — use carefully, log accesses"}]},{"slug":"LONE_SKILL_DISPATCH_FORBIDDEN","kind":"constitutional","domain":"security","title":"Skills are not directly invokable outside of skill-internal composition","statement":"Every user/AI-initiated work passes through an action (system.action.run, MCP tool, or bin/antiloki <action>). Skills are atomic units composed BY actions or BY other skills; they are NOT a public API surface. The only escape hatch is `--unsafe-skill --as god` from an interactive TTY (for human debug). AI subprocesses, scripts, and non-god callers must never import a skill directly and invoke it.","rationale":"Skill-direct dispatch bypasses the action dispatcher, which is where permission checks, audit logging (sacred_timeline), and law enforcement live. A \"lone skill\" call leaves no audit row and no permission boundary, making the substrate non-replayable and unsafe. The substrate is only \"deterministic + auditable\" because every mutation flows through the gated dispatcher.","enforcement":"hard","enforcement_hook":"law-hook-no-lone-skill-dispatch","established_by":"human:dani+claude","source_card":"FEAT-NO-LONE-SKILL-DISPATCH","clauses":[{"clause_type":"example","text":"Skill A imports skill B and calls B() — allowed (internal composition)."},{"clause_type":"example","text":"action.steps_json references a skill name — allowed (this is the substrate's composition pattern)."},{"clause_type":"example","text":"Human types `antiloki --unsafe-skill foo` in a TTY with --as god — allowed (escape hatch)."},{"clause_type":"antipattern","text":"bin/some-script.mjs imports a skill from .antiloki/skills/entities/ and calls it (not in TTY+god context) — forbidden."},{"clause_type":"antipattern","text":"MCP server attempts to call an unmapped skill name directly — forbidden."},{"clause_type":"antipattern","text":"Test file outside .antiloki/skills/ imports a skill directly to bypass action gating — forbidden."},{"clause_type":"consequence","text":"consistency-scan dimension SKILL_DIRECT_IMPORT flags violations as critical."}]},{"slug":"READ_BEFORE_WRITING","kind":"procedural","domain":"dev","title":"Always read the file (or grep) before editing it","statement":"Before any non-trivial edit, read the file or grep for the relevant section. Files over 200 lines: read the section plus immediate neighbors. Do not rely on memory of files from earlier sessions — they may have changed.","rationale":"Edit-without-reading is the #1 cause of broken changes. The code on disk may differ from your mental model.","enforcement":"soft","established_by":"system:bootstrap"},{"slug":"AFTER_CORRECTION_UPDATE_MEMORY","kind":"procedural","domain":"memory","title":"When the human corrects your approach, record a memory immediately","statement":"Any correction from the human (push-back, \"no\", \"stop doing X\", \"actually it should be Y\") triggers system.memory.add with type=correction, preserving both the naive_response and the corrected guidance.","rationale":"Corrections evaporate at /clear. Future-AI cold-starts will repeat the same mistake unless the correction is captured. This is the foundation of the self-learning loop (memory_uses + memory_use_outcomes).","enforcement":"soft","established_by":"human:dani"},{"slug":"RECORD_DECISION_AS_MEMORY","kind":"procedural","domain":"memory","title":"Significant decisions become memory entries with type=decision","statement":"Whenever the conversation produces a non-trivial decision (architectural, technological, procedural), record it via system.memory.add with type=decision, capturing situation + guidance + rationale + alternatives considered.","rationale":"Surfaced 2026-05-18 when human:dani asked \"are we doing the best to AI understand the journey of the code?\" — answer was no, infrastructure existed but discipline did not. Without this habit, future-AI rederives decisions cold.","enforcement":"soft","established_by":"human:dani"},{"slug":"RECORD_NAIVE_RESPONSE_ON_CORRECTION","kind":"procedural","domain":"memory","title":"On correction, preserve the naive answer alongside the corrected guidance","statement":"When recording a correction memory, include the original (naive_response) AND the corrected guidance. This creates DPO-style preference pairs usable for fine-tuning.","rationale":"The naive answer is the SIGNAL — it tells future training that this was a likely-but-wrong reasoning path. Discarding it loses half the learning data.","enforcement":"soft","established_by":"human:dani+claude"},{"slug":"TESTS_AFTER_MACRO_TASK","kind":"procedural","domain":"dev","title":"Run tests after each macro task completes","statement":"When finishing a macro task (M1, M2, etc.) in a plan, run the relevant tests before declaring the task done. For substrate work (engine, schema, runner), run the full suite.","rationale":"Tests are the fastest feedback loop. Discovering a regression at macro-task boundary is cheap; discovering it 3 macro tasks later means tracing through more code.","enforcement":"soft","established_by":"human:dani"},{"slug":"ASK_BEFORE_DESTRUCTIVE","kind":"procedural","domain":"security","title":"Confirm before destructive operations even if previously authorized","statement":"rm -rf, force push, DROP TABLE, mass renames, deletions, overwriting uncommitted work — all require explicit confirmation in the current turn. Past authorization does not carry forward.","rationale":"Reversibility is the differentiator. Local edits are cheap to undo; destructive ops can lose hours of work. Cost of asking: low. Cost of unwanted destruction: high.","enforcement":"soft","established_by":"system:bootstrap"},{"slug":"COMMIT_CODE_BEFORE_AUDIT_COMMIT","kind":"procedural","domain":"audit","title":"Code changes must be committed before audit-card auto-commits","statement":"When the working tree has uncommitted code files (anything outside AUDIT_MANAGED_PATHS), git-commit-card detects drift. Per the LAW-SCHEMA card decision, this becomes HARD: drift detection blocks the audit-card auto-commit unless ANTILOKI_ALLOW_DRIFT=true is set.","rationale":"Surfaced 2026-05-18 when 16 audit-card commits piled up in git log while 80 code files stayed uncommitted. Auto-commits created the ILLUSION of progress and masked the real state. Future-AI looking at git log saw activity; reality was the code was ephemeral.","enforcement":"hard","enforcement_hook":"law-hook-no-drift-on-audit-commit","established_by":"human:dani+claude","source_card":null,"clauses":[{"clause_type":"consequence","text":"~6 hours of work was ephemeral on disk before audit caught it. Required forensic git diff to recover into proper commits."},{"clause_type":"exception","text":"ANTILOKI_ALLOW_DRIFT=true env var skips the check — use for explicit audit-only operations"}]},{"slug":"SKILL_EXPORTS_DEFAULT_FUNCTION","kind":"constraint","domain":"architecture","title":"Every dispatchable skill exports exactly one default function","statement":"Dispatchable skills under antiloki-core/skills/**/*.mjs (excluding *.test.mjs) must have exactly one `export default` and it must be a function taking (input, context). Non-skill modules in the same tree are deliberate parallel contracts, not violations: _helpers/ plus schema/data modules (canonical-* shards, open-db/schemas+seed) export named symbols only, and skills/reconcilers/ default-exports {id, detect, fix, safety} objects validated by its own registry loader. The lint ratchet (audit/lint-all-skills.test.mjs) blocks NEW non-conforming modules; the legacy set may only shrink.","rationale":"Skills are the deterministic atomic units — the dispatcher (load-skill + action-run) assumes one uniform contract so calling code never needs per-skill shaping. Supersedes SKILL_MUST_EXPORT_DEFAULT_FUNCTION (2026-07-12): it pointed at .antiloki/skills/**, a directory that no longer exists since the core carve-out, and its blanket every-file reading had 60+ deliberate counter-examples, leaving the law unenforceable as written while the real contract went unstated.","enforcement":"hard","enforcement_hook":null,"enforcement_layer":"compile_time:lint-skill","established_by":"human:danil+claude"},{"slug":"SKILL_DEFAULT_TAKES_INPUT_CONTEXT","kind":"constraint","domain":"architecture","title":"Skill default export takes exactly (input, context)","statement":"The default exported function must take 2 parameters named input and context. The action-run dispatcher always passes resolved input + the runtime context object.","rationale":"Uniform calling convention. Mixed signatures would force the dispatcher to do per-skill argument shaping.","enforcement":"hard","enforcement_hook":null,"enforcement_layer":"compile_time:lint-skill","established_by":"system:bootstrap"},{"slug":"ENTITY_ID_STORED_AS_STRING","kind":"constraint","domain":"audit","title":"sacred_timeline.entity_id is always a string (TEXT column)","statement":"When passing entity_id to with-audit, coerce to String(). SQLite TEXT column will accept integers via type affinity but represents them differently than the digital_print computation expects, breaking chain verification.","rationale":"Lesson from v0.7.1: passing integer entity_id=1 caused SQLite to store \"1.0\" via TEXT affinity. digital_print was computed from integer 1 → verify-chain rehashed from \"1.0\" → mismatch. Fix landed in with-audit: const entity_id_str = String(entity_id) before INSERT.","enforcement":"hard","enforcement_hook":null,"enforcement_layer":"internal:with-audit","established_by":"claude"},{"slug":"EVERY_MUTATION_GOES_THROUGH_WITH_AUDIT","kind":"constraint","domain":"audit","title":"No skill writes to audited entities without composing with-audit","statement":"Skills that mutate cards/agents/actions/memory.memories/laws.laws must either BE wrapped by with-audit at the action layer, OR call with-audit internally. Detect-bypass (runtime) + AST static analysis (planned) enforce this.","rationale":"Without this constraint, an agent could write a skill that updates cards directly, bypassing the audit chain even though law NEVER_BYPASS_WITH_AUDIT exists at the action layer. Defense in depth: schema design + lint + AST + runtime detection.","enforcement":"hard","enforcement_hook":null,"enforcement_layer":"compile_time:detect-bypass","established_by":"system:bootstrap"},{"slug":"SACRED_TIMELINE_ROWS_MUST_HAVE_DIGITAL_PRINT","kind":"constraint","domain":"audit","title":"sacred_timeline rows are immutable + must carry a digital_print","statement":"sacred_timeline rows, once inserted, cannot be UPDATEd or DELETEd. The chain integrity depends on rows being write-once. Triggers at the DB layer block all UPDATE/DELETE on this table.","rationale":"The Merkle chain assumes append-only. If sacred_timeline rows can be UPDATEd after insertion, the digital_print computed during INSERT would no longer match the stored row contents, silently breaking verify-chain. This is the deepest enforcement layer — even --unsafe-skill cannot bypass an SQLite trigger.","enforcement":"hard","enforcement_hook":null,"enforcement_layer":"db_trigger:sacred_timeline_immutable","trigger_sql":"CREATE TRIGGER IF NOT EXISTS timeline.sacred_timeline_no_update\n                  BEFORE UPDATE ON sacred_timeline\n                  BEGIN\n                    SELECT RAISE(ABORT, 'sacred_timeline rows are immutable (law: SACRED_TIMELINE_ROWS_MUST_HAVE_DIGITAL_PRINT)');\n                  END;\n                  CREATE TRIGGER IF NOT EXISTS timeline.sacred_timeline_no_delete\n                  BEFORE DELETE ON sacred_timeline\n                  BEGIN\n                    SELECT RAISE(ABORT, 'sacred_timeline rows are immutable — no DELETE (law: SACRED_TIMELINE_ROWS_MUST_HAVE_DIGITAL_PRINT)');\n                  END;","established_by":"human:dani+claude","source_card":"LAW-ENFORCEMENT-TRIGGERS"},{"slug":"EMBEDDINGS_VIA_TRANSFORMERS_JS_BGE_BASE","kind":"decision","domain":"architecture","title":"Embeddings: transformers.js with Xenova/bge-base-en-v1.5 (768-dim, WASM)","statement":"Use @huggingface/transformers locally with the Xenova/bge-base-en-v1.5 model. 768-dimensional vectors. WASM backend (no native build). Initial recommendation was Voyage API — corrected to local-first.","rationale":"Matches zero-deps + privacy + no-vendor-risk principles. FASTER warm-path than Voyage (10-30ms local vs 150-400ms network). Quality within 2-3% of voyage-3-lite on MTEB. Switching cost later is just re-embedding (cheap, ~3 min for 10k memories). Schema embeddings.model column supports later provider addition without breaking existing vectors.","enforcement":"soft","established_by":"human:dani+claude","source_card":"V08-EMBEDDINGS-WIRE"},{"slug":"RUNTIME_NODE_NOT_BUN","kind":"decision","domain":"architecture","title":"Runtime: Node 24, not Bun","statement":"The runtime is Node.js 24 (or current LTS+1). Bun was considered and rejected for this project.","rationale":"App is built/tested/working on Windows. Bun + Windows + ONNX is the weakest matrix. Migration cost > benefit for this workload. Bun was great for greenfield projects on Mac/Linux; not here. Revisit if Bun on Windows matures significantly or new project starts greenfield.","enforcement":"soft","established_by":"human:dani+claude","source_card":"V08-EMBEDDINGS-WIRE"},{"slug":"AI_NAMING_TIER_TEMPERATURE","kind":"decision","domain":"architecture","title":"AI capability tier (low/mid/high) and temperature (freezed/cold/warm/hot/hell) — provider-agnostic","statement":"All AI call-sites use the provider-agnostic naming: tier ∈ {low, mid, high} and temperature ∈ {freezed, cold, warm, hot, hell} (mapping to 0.0/0.2/0.5/0.8/1.0+). Provider/model mapping lives in brain.ai_providers (swap via SQL). Routing decisions live in brain.routing_defaults. The string \"claude\" or \"haiku/sonnet/opus\" must never appear in call-site code outside the provider table.","rationale":"Decouples the substrate from any single provider. Replacing a provider becomes a SQL UPDATE, not a code refactor. Tier/temperature semantics survive across providers (a \"high\" model means deep cognition regardless of vendor). Established 2026-05-18 during PL-V2 brainstorm.","enforcement":"soft","established_by":"human:dani+claude","source_card":"AI-NAMING-CONVENTION","clauses":[{"clause_type":"example","text":"system.ai.route returns {tier: \"mid\", temperature: \"cold\"} — caller never sees \"sonnet\""},{"clause_type":"antipattern","text":"Hardcoding \"claude-sonnet-4-6\" in a action body"},{"clause_type":"consequence","text":"Swap provider: UPDATE brain.ai_providers SET active=0 WHERE provider=\"anthropic\"; INSERT new row"}]},{"slug":"MULTI_DB_SPLIT_BY_QUADRANT","kind":"decision","domain":"architecture","title":"Orthogonal SQLite databases attached via ATTACH — one per concern","statement":"Storage splits into orthogonal SQLite databases attached onto one connection: state.sqlite (what the system IS), memory.sqlite (what it EXPERIENCED), brain.sqlite (what it DOES/THINKS), laws.sqlite (what it MUST/MUST NOT do), knowledge.sqlite (what it LEARNED from external sources), timeline.sqlite (the sacred_timeline audit chain), judgments.sqlite (swarm audit verdicts), code.sqlite (the code atlas), nb.sqlite (notebooks). The authoritative census is PRAGMA database_list on a live connection, mirrored by the committed schema baseline (open-db/schema-baseline.json) — never a number hardcoded in prose.","rationale":"Each DB owns one quadrant of system reality. Atomicity is preserved via ATTACH; SQLite forbids cross-DB FKs, so references use TEXT slug convention. Splits happened only when orthogonality forced them (1 → 2 → 3 → 4 → … → 9). Supersedes FOUR_DB_SPLIT_STATE_MEMORY_BRAIN_LAWS (2026-07-12): AGENTS.md renders from these laws, and the 4-database text shipped wrong context to every AI session for weeks — the drift this replacement words itself to prevent (derive the census, never restate it).","enforcement":"soft","established_by":"human:danil+claude","source_card":"LAW-SCHEMA"},{"slug":"AGENT_SKILLS_RELATIONAL_NOT_DENORMALIZED","kind":"decision","domain":"architecture","title":"Agent → action permissions live in agent_actions table","statement":"Agent action grants are stored in the agent_actions relational table (with append-only revoked_at), not denormalized in agents.skills_json. Queryable, FK-validated, audit-able grants.","rationale":"Surfaced when designing 5-persona model — needed enforcement-grade permissions. Denormalized JSON arrays cannot be efficiently queried for \"all agents that can call action X\" and have no FK integrity. Steps_json deliberately stays JSON (workflow document, not relation — different concern).","enforcement":"soft","established_by":"human:dani+claude"},{"slug":"STEPS_JSON_STAYS_WORKFLOW_DOC","kind":"decision","domain":"architecture","title":"actions.steps_json stays as a JSON workflow document","statement":"Action step lists are ordered workflows with input mapping (input/wrappedInput/$.path resolution) and output aliasing (as). They stay as JSON in actions.steps_json, NOT normalized into a separate steps table.","rationale":"Steps are ordered documents with structure (input mapping, conditionals planned). Normalizing into rows requires step_order + input_mapping_json + output_alias + condition_expr columns — at which point you have JSON-in-columns with extra ceremony. JSON-in-one-column preserves diff readability and document semantics.","enforcement":"soft","established_by":"human:dani+claude"},{"slug":"SKILLS_SHARED_ACTIONS_AGENT_NAMESPACED","kind":"decision","domain":"architecture","title":"Skills shared across actions; actions agent-namespaced","statement":"Skills are pure logic shared by any action that needs the mechanism. Actions carry the AGENT INTENT — they are \"cognition inserts\" (human:dani phrasing). dev.card.add and man.card.add can both wrap the same card-add skill, with different permissions + different context implications.","rationale":"Less cognition, more deterministic. The skill encodes HOW to perform an operation. The action encodes WHY the agent is doing it. Agents query the action catalog (which is agent-aware); the skill catalog is internal. This separation forms the architectural backbone of agent identity.","enforcement":"soft","established_by":"human:dani"},{"slug":"AUDIT_GAP_CANARY_TESTS","kind":"decision","domain":"audit","title":"Canary tests guard against re-introduction of audit-bypass patterns","statement":"When an audit gap is discovered + closed (e.g., GAP-CARD-UPDATE-ACTION), a canary test is added that BREAKS LOUDLY if anyone refactors with-audit such that the bypass is no longer detectable. The test asserts the silent failure mode itself.","rationale":"A fix is one commit. A canary preserves the LESSON forever. When someone tries to \"clean up\" with-audit and accidentally makes direct UPDATEs audited too, the canary breaks with a clear message explaining why the original design was deliberate.","enforcement":"soft","established_by":"human:dani+claude","source_card":"GAP-CARD-UPDATE-ACTION"},{"slug":"ACTION_NAME_ENCODES_INTENT_SKILL_ENCODES_MECHANISM","kind":"decision","domain":"architecture","title":"Action names express agent intent; skill names express mechanism","statement":"Action names follow agent.action.target (dev.file.write, man.card.add). Skill names describe the mechanism in plain terms (card-add, file-write, with-audit). When debugging audit logs, the operation field carries the intent (card.add via dev), the skill executions reveal the mechanism.","rationale":"Same mechanism (card-add skill) used by different intents (dev.card.add vs man.card.add) means: maintenance fixes one place but all wrappers benefit. Renaming a skill would break all action steps_json — so they are stable contract surfaces.","enforcement":"soft","established_by":"human:dani+claude"},{"slug":"SURGICAL_EDITS","kind":"principle","domain":"dev","title":"Every changed line must trace directly to the request","statement":"Do not refactor adjacent code, \"improve\" comments, reformat unrelated sections, or fix pre-existing dead code in passing. Each line in the diff has a reason traceable to the user request.","rationale":"Mixing concerns in one change makes reviews harder and bisecting failures worse. Drive-by improvements are still improvements — but they belong in their own PR.","enforcement":"soft","established_by":"system:bootstrap"},{"slug":"MINIMUM_VIABLE_CHANGE","kind":"principle","domain":"dev","title":"Write the least code that solves the stated problem","statement":"No features, abstractions, or configurability that were not asked for. No speculative flexibility. If 200 lines could be 50, rewrite. Resist anticipated-need futureproofing — wait for the second occurrence before generalizing.","rationale":"YAGNI compounds. Each anticipated feature you build is one more thing to maintain, test, and explain to future-AI. Speculative complexity is the silent killer.","enforcement":"soft","established_by":"system:bootstrap"},{"slug":"DEFAULT_TO_NO_COMMENTS_EXPLAIN_WHY_ONLY","kind":"principle","domain":"dev","title":"Default to no comments; add them only for non-obvious WHY","statement":"Code with well-named identifiers does not need WHAT comments. Add comments only when the WHY is hidden (a constraint, a subtle invariant, a workaround for a specific bug, behavior that would surprise a reader). Do not write multi-paragraph docstrings except for module headers explaining the substrate-level role.","rationale":"Comments rot faster than code. A wrong comment is worse than no comment. Save comment budget for the cases where they prevent real confusion.","enforcement":"soft","established_by":"system:bootstrap"},{"slug":"LESS_COGNITION_MORE_DETERMINISTIC","kind":"principle","domain":"architecture","title":"Prefer deterministic enforcement over advisory rules","statement":"When designing a constraint, ask: can this be enforced by the system instead of remembered by the AI? Move rules from \"AI should remember\" to \"system blocks at runtime.\" This entire laws.sqlite stack exists because of this principle — laws-in-DB beats laws-in-MD.","rationale":"AI memory is fallible. Determinism is the substrate. Every law captured here is a piece of cognition the AI no longer has to carry — the system carries it.","enforcement":"soft","established_by":"human:dani","source_card":"LAW-SCHEMA"},{"slug":"CLAIM_REQUIRES_VERIFICATION","kind":"procedural","domain":"workflow","title":"Every \"I built X\" claim must carry a verification command","statement":"When AI asserts \"I did X\" or \"X works\", the same response must include a verification command the user can run plus expected output. Claims without verification paths are unverifiable assertions.","rationale":"AI optimism bias: tendency to claim success when uncertain. 2026-05-18 audit found 3 wrong claims in one session (wrong MCP path, 11 unfiled cards, unrendered CLAUDE.md). Verification commands turn assertions into checkable propositions.","enforcement":"soft","established_by":"human:dani+claude","clauses":[{"clause_type":"antipattern","text":"Response says X works with no command to verify"},{"clause_type":"example","text":"I built X — verify via: node bin/antiloki.mjs Y — expected: Z"}]},{"slug":"CARD_STATUS_MIRRORS_REALITY","kind":"procedural","domain":"workflow","title":"When card work completes, card.status.change fires in the same turn","statement":"If AI claims a card is done, board-keeper.card.status.change must be invoked in the same response. Prose claiming completion without status update creates board lies.","rationale":"V08-EMBEDDINGS-WIRE failure 2026-05-18: work shipped + tested + committed but card status stayed backlog. Future-AI reads the BOARD not the conversation. Status divergence is the lie.","enforcement":"soft","established_by":"human:dani+claude","clauses":[{"clause_type":"antipattern","text":"Commit message announces card X complete; no status.change action invocation in same turn"},{"clause_type":"consequence","text":"Card stays backlog. consistency-scan eventually catches it but only on demand."}]},{"slug":"BATCH_OPERATIONS_VERIFY_COUNT","kind":"procedural","domain":"workflow","title":"After batch operations, verify resulting count matches expectation","statement":"When AI claims filed/inserted N items, the next action must be a count query confirming N rows landed.","rationale":"2026-05-18 incident: shell script printed 11 checkmarks based on its own log; AI claimed 11 cards filed; reality was 1 because bash quoting ate the JSON. Count-after-insert closes the loop in seconds.","enforcement":"soft","established_by":"human:dani+claude","clauses":[{"clause_type":"example","text":"After batch insert: SELECT COUNT(*) FROM cards WHERE slug LIKE pattern — verify count matches"}]},{"slug":"FILE_PATHS_FOLLOW_TOOL_CONVENTIONS","kind":"constraint","domain":"integration","title":"Config files live where the consuming tool actually looks","statement":"Configuration files for external tools (MCP, Claude Code instructions, IDE configs) must be placed at the path the tool documents/auto-discovers, NOT a path resembling other projects conventions. .mcp.json at repo root, NOT .claude/mcp.json. CLAUDE.md at repo root, NOT .claude/rules/CLAUDE.md.","rationale":"2026-05-18 incidents: wrong MCP path (silently ignored), wrong CLAUDE.md path (laws never reached Claude Codes working context). Pattern: copying convention from project A without verifying it applies to project B.","enforcement":"hard","enforcement_hook":null,"enforcement_layer":"compile_time:consistency-scan","established_by":"human:dani+claude","clauses":[{"clause_type":"antipattern","text":"Placing config at .claude/X because antiloki-1 used .claude/ — but Claude Code reads at repo root"},{"clause_type":"example","text":"Before placing: check tool docs OR cross-terminal verify with fresh Claude session"},{"clause_type":"consequence","text":"Wrong-path config silently ignored. AI claims wiring done; user discovers it isnt. consistency-scan dimensions catch this."}]}]"#).expect("CANONICAL_LAWS: embedded JSON is valid by construction")
});

/// JS: `canonicalLaws(_input, _context)` — returns the canonical data, verbatim.
pub fn canonicalLaws(_input: &Value, _context: &Value) -> Value {
    CANONICAL_LAWS.clone()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn canonical_laws_parses_with_the_pressed_shape() {
        let v: &Value = &CANONICAL_LAWS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 35, "pressed length");
    }

    #[test]
    fn canonicallaws_returns_the_static_verbatim() {
        assert_eq!(canonicalLaws(&Value::Null, &Value::Null), *CANONICAL_LAWS);
    }

}
